import { Component, input, output } from '@angular/core';
import { Observacion, ObservacionTarget } from '../../models/observacion.model';
import { DocumentoResumen } from '../../models/solicitud.model';

const FIELD_LABELS: Record<string, string> = {
  solicitante: 'Nombre completo',
  denominacionRazonSocial: 'Denominación o razón social',
  rfc: 'RFC',
  email: 'Correo electrónico',
  tieneRepresentanteLegal: '¿Cuenta con representante legal?',
  numeroFolio: 'Número o folio de la póliza o acta constitutiva',
  fechaOtorgamiento: 'Fecha de otorgamiento',
  nombreRepresentante: 'Nombre del representante',
  primerApellidoRepresentante: 'Primer apellido del representante',
  segundoApellidoRepresentante: 'Segundo apellido del representante',
  proyecto: 'Nombre del proyecto',
};

const SECTION_LABELS: Record<string, string> = {
  'info-general': 'Datos del inversionista',
  'detalles-inversion': 'Detalles de la inversión',
  fechas: 'Fechas',
  proyecto: 'Información del proyecto',
  documentos: 'Documentos adjuntos',
};

@Component({
  selector: 'app-observacion-sidebar',
  imports: [],
  templateUrl: './observacion-sidebar.component.html',
  host: { class: 'd-block' },
})
export class ObservacionSidebarComponent {
  observaciones = input.required<Observacion[]>();
  modoEdicion = input(false);
  documentos = input<DocumentoResumen[]>([]);
  solicitudStatus = input<string>('');

  irA = output<ObservacionTarget>();
  corregida = output<number>();
  editarObservacion = output<Observacion>();
  eliminarObservacion = output<number>();

  targetLabel(obs: Observacion): string {
    const t = obs.target;
    switch (t.type) {
      case 'field':
        return `Campo: ${FIELD_LABELS[t.fieldId] ?? t.fieldId}`;
      case 'section':
        return `Sección: ${SECTION_LABELS[t.sectionId] ?? t.sectionId}`;
      case 'document': {
        const doc = this.documentos().find((d) => d.id === t.documentId);
        if (doc) {
          return `Documento: ${doc.nombreOriginal} (${doc.tipoDocumento?.nombre ?? 'Documento'})`;
        }
        return `Documento: #${t.documentId}`;
      }
    }
  }

  irButtonLabel(obs: Observacion): string {
    switch (obs.target.type) {
      case 'field':
        return 'Ir al campo';
      case 'section':
        return 'Ir a la sección';
      case 'document':
        return 'Ir al documento';
    }
  }

  onIrA(target: ObservacionTarget): void {
    this.irA.emit(target);
  }

  onCorregida(id: number): void {
    this.corregida.emit(id);
  }

  onEditarObservacion(obs: Observacion): void {
    this.editarObservacion.emit(obs);
  }

  onEliminarObservacion(id: number): void {
    this.eliminarObservacion.emit(id);
  }
}
